package shop.ultimatesmp.network.paper;
import java.lang.reflect.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.function.Consumer;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.event.entity.*;import org.bukkit.event.server.TabCompleteEvent;
import org.bukkit.plugin.Plugin;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.plugin.messaging.PluginMessageListener;
import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.scheduler.BukkitTask;
import com.destroystokyo.paper.event.server.AsyncTabCompleteEvent;
import net.kyori.adventure.text.Component;import shop.ultimatesmp.network.*;
public final class UltimateNetworkPaper extends JavaPlugin implements Listener,PluginMessageListener {
 private Plugin network;private Method ready,home;private final Map<UUID,String> lastState=new HashMap<>();private final Map<UUID,Long> lastSent=new HashMap<>(),proxySeen=new HashMap<>();
 private record Remote(UUID id,String name,String server){}
 private final Map<UUID,Set<String>> tabPermissions=new ConcurrentHashMap<>();
 private final Map<UUID,List<Remote>> rosters=new ConcurrentHashMap<>();
 private record Warmup(Wire frame,Player player,Location origin,Location destination,String dimension,long due,UUID target){}
 private final Map<UUID,Warmup> warming=new HashMap<>();private final Set<UUID> networkVanish=new HashSet<>();
 private final Map<UUID,BukkitTask> delayed=new HashMap<>();
 @Override public void onEnable(){
  saveDefaultConfig();network=Bukkit.getPluginManager().getPlugin("BlinkNetwork");
  try{ready=network.getClass().getMethod("isPlayerReady",Player.class);home=network.getClass().getMethod("networkHomeTeleport",Player.class,String.class,double.class,double.class,double.class,float.class,float.class);}catch(Exception ex){getLogger().severe("Requires BlinkNetwork-Paper 0.5.1 or newer. Install the matching network update.");Bukkit.getPluginManager().disablePlugin(this);return;}
  if(!((JavaPlugin)network).getConfig().getBoolean("proxy-security-configured",false)){getLogger().severe("Modern forwarding/proxy security must be confirmed in BlinkNetwork config.");Bukkit.getPluginManager().disablePlugin(this);return;}
  Bukkit.getMessenger().registerOutgoingPluginChannel(this,Wire.CHANNEL);Bukkit.getMessenger().registerIncomingPluginChannel(this,Wire.CHANNEL,this);Bukkit.getPluginManager().registerEvents(this,this);
  Bukkit.getScheduler().runTaskTimer(this,()->{for(Player p:Bukkit.getOnlinePlayers())publish(p,false);pulse();},10,5);
  getLogger().info("UltimateNetwork ready. Internal server switches are silent; Velocity owns network join/leave messages.");
 }
 private Plugin plugin(String name){Plugin p=Bukkit.getPluginManager().getPlugin(name);return p!=null&&p.isEnabled()?p:null;}
 private Object invoke(String plugin,String method,Class<?>[] types,Object...args)throws ReflectiveOperationException{Plugin p=plugin(plugin);if(p==null)throw new IllegalStateException(plugin+" is unavailable");return p.getClass().getMethod(method,types).invoke(p,args);}
 private boolean bool(String plugin,String method,UUID id,boolean fallback){try{return (Boolean)invoke(plugin,method,new Class[]{UUID.class},id);}catch(Exception ex){return fallback;}}
 private String authority(UUID id){try{return (String)invoke("UltimateRanks","getNetworkAuthority",new Class[]{UUID.class},id);}catch(Exception ex){return "MEMBER";}}
 private boolean ready(Player p){try{return (Boolean)ready.invoke(network,p);}catch(Exception ex){return false;}}
 private boolean hidden(Player p){return networkVanish.contains(p.getUniqueId())||bool("UltimateGUI","isVanished",p.getUniqueId(),false)||bool("UltimateRanks","isLocallyVanished",p.getUniqueId(),false);}
 private String rankPrefix(UUID id){try{return (String)invoke("UltimateRanks","getRankPrefix",new Class[]{UUID.class},id);}catch(Exception ex){return "";}}
 private String rankWeight(UUID id){try{return ""+invoke("UltimateRanks","getRankWeight",new Class[]{UUID.class},id);}catch(Exception ex){return "0";}}
 private boolean muted(Player p){return bool("UltimateRanks","isNetworkMuted",p.getUniqueId(),false);}
 private boolean usable(Player p){return p.isOnline()&&ready(p)&&!p.isDead()&&!p.isSleeping()&&!p.isInsideVehicle()&&p.getPassengers().isEmpty()&&!bool("UltimateRanks","isNetworkFrozen",p.getUniqueId(),false);}
 private void tell(Player p,String s){p.sendMessage(Component.text("[UltimateSMP] "+s));}
 private void send(Player p,Wire f){p.sendPluginMessage(this,Wire.CHANNEL,f.encode());}
 private void publish(Player p,boolean force){if(!p.isOnline())return;
 Set<String> permissions=new HashSet<>();for(String c:List.of("tp","bring","invsee","heal","feed","warn","warnings","kick","ban","tempban","mute","unmute","unban","freeze","rank","staffchat","trade","tpr","maxhomes")){String permission=Commands.permission(c);if(permission!=null&&p.hasPermission(permission))permissions.add(permission);}tabPermissions.put(p.getUniqueId(),Set.copyOf(permissions));UUID id=p.getUniqueId();List<String> fields=List.of(""+hidden(p),""+bool("UltimateSettings","allowsNetworkMessages",id,true),""+bool("UltimateSettings","allowsNetworkJoinMessages",id,true),""+bool("UltimateSettings","showsNetworkPlayers",id,true),authority(id),""+ready(p),""+bool("UltimateTrades","canNetworkTrade",id,false),""+muted(p),""+p.hasPermission("ultimatehomes.admin"),""+bool("UltimateSettings","showRankTags",id,true),rankPrefix(id),rankWeight(id),""+bool("UltimateTrades","networkRequestsEnabled",id,true));String state=String.join("|",fields);long now=System.currentTimeMillis();if(force||!state.equals(lastState.get(id))||now-lastSent.getOrDefault(id,0L)>5000){lastState.put(id,state);lastSent.put(id,now);send(p,new Wire(UUID.randomUUID(),"STATE",id,fields));}}
 public void publishNetworkState(Player p){if(Bukkit.isPrimaryThread()&&p.isOnline())publish(p,true);}
 @EventHandler(priority=EventPriority.MONITOR) public void personalMenu(org.bukkit.event.inventory.InventoryClickEvent e){if(e.getWhoClicked() instanceof Player p){var holder=e.getView().getTopInventory().getHolder();if(holder!=null&&(holder.getClass().getName().startsWith("shop.blinksmp.gui.")||holder.getClass().getName().startsWith("shop.blinksmp.settings.")))publish(p,true);}}
 public boolean handlesNetworkPresence(){return isEnabled();}
 public UUID findNetworkPlayer(String name){return rosters.values().stream().flatMap(List::stream).filter(p->p.name.equalsIgnoreCase(name)||p.id.toString().equalsIgnoreCase(name)).map(Remote::id).findFirst().orElse(null);}
 public boolean broadcastNotice(String display,List<String> lines,int duration){Player p=Bukkit.getOnlinePlayers().stream().findFirst().orElse(null);if(p==null)return false;List<String> args=new ArrayList<>(List.of(display,""+duration));args.addAll(lines);send(p,new Wire(UUID.randomUUID(),"NOTICE",p.getUniqueId(),args));return true;}
 public boolean broadcastNetwork(String text){if(text==null||text.isBlank()||text.length()>4096)return false;Player carrier=Bukkit.getOnlinePlayers().stream().findFirst().orElse(null);if(carrier==null)return false;send(carrier,Wire.of("ANNOUNCE",carrier.getUniqueId(),text));return true;}
 @EventHandler(priority=EventPriority.LOWEST) public void quietJoin(PlayerJoinEvent e){e.joinMessage(null);}
 @EventHandler(priority=EventPriority.HIGHEST) public void quietJoinLast(PlayerJoinEvent e){e.joinMessage(null);}
 @EventHandler(priority=EventPriority.LOWEST) public void quietQuit(PlayerQuitEvent e){e.quitMessage(null);UUID id=e.getPlayer().getUniqueId();warming.remove(id);networkVanish.remove(id);lastState.remove(id);lastSent.remove(id);proxySeen.remove(id);rosters.remove(id);tabPermissions.remove(id);BukkitTask t=delayed.remove(id);if(t!=null)t.cancel();}
 @EventHandler(priority=EventPriority.HIGHEST) public void quietQuitLast(PlayerQuitEvent e){e.quitMessage(null);}
 @Override public void onPluginMessageReceived(String channel,Player carrier,byte[] data){if(!Wire.CHANNEL.equals(channel))return;try{Wire f=Wire.decode(data);if(!f.actor().equals(carrier.getUniqueId()))return;proxySeen.put(carrier.getUniqueId(),System.currentTimeMillis());switch(f.kind()){
  case "HELLO" -> publish(carrier,true);
  case "ROSTER_BEGIN" -> rosters.put(carrier.getUniqueId(),List.of());
  case "ROSTER" -> {List<Remote> list=new ArrayList<>(rosters.getOrDefault(carrier.getUniqueId(),List.of()));for(String row:f.args()){String[] a=row.split("\\|",-1);if(a.length!=3||!a[1].matches("[A-Za-z0-9_. -]{1,32}")||a[2].length()>64)throw new IllegalArgumentException();list.add(new Remote(UUID.fromString(a[0]),a[1],a[2]));}rosters.put(carrier.getUniqueId(),List.copyOf(list));}
  case "NOTICE" -> invoke("UltimateAnnouncements","showNetworkNotice",new Class[]{Player.class,String.class,List.class,int.class},carrier,f.at(0),f.args().subList(2,f.args().size()),Integer.parseInt(f.at(1)));
  case "TRADE_PREF" -> {invoke("UltimateTrades","setNetworkRequestsEnabled",new Class[]{UUID.class,boolean.class},carrier.getUniqueId(),Boolean.parseBoolean(f.at(0)));publish(carrier,true);}
  case "LOCATE" -> locate(carrier,f);
  case "MOVE" -> move(carrier,f);
  case "CANCEL" -> {Warmup w=warming.get(carrier.getUniqueId());if(w!=null&&w.frame.id().equals(f.id())){warming.remove(carrier.getUniqueId());tell(carrier,"Teleport cancelled.");}}
  case "STAFF" -> staff(carrier,f);
  case "VANISH" -> {if(Boolean.parseBoolean(f.at(0))){networkVanish.add(carrier.getUniqueId());try{Plugin gui=plugin("UltimateGUI");if(gui!=null&&(Boolean)gui.getClass().getMethod("controlsVanish",UUID.class).invoke(gui,carrier.getUniqueId()))gui.getClass().getMethod("setOwnerVanish",Player.class,boolean.class).invoke(gui,carrier,true);else invoke("UltimateRanks","setNetworkVanish",new Class[]{Player.class,boolean.class},carrier,true);networkVanish.remove(carrier.getUniqueId());publish(carrier,true);}catch(Exception ex){tell(carrier,"Vanish could not be restored; staff travel is blocked.");}}}
  case "TRADE_OPEN","INSPECT" -> {UUID other=UUID.fromString(f.at(0));BukkitTask previous=delayed.remove(carrier.getUniqueId());if(previous!=null)previous.cancel();BukkitTask task=Bukkit.getScheduler().runTaskTimer(this,new Runnable(){int tries;public void run(){Player target=Bukkit.getPlayer(other);if(++tries>100||!carrier.isOnline()||target==null){BukkitTask t=delayed.remove(carrier.getUniqueId());if(t!=null)t.cancel();return;}if(!ready(carrier)||!ready(target))return;BukkitTask t=delayed.remove(carrier.getUniqueId());if(t!=null)t.cancel();try{if(f.kind().equals("TRADE_OPEN"))invoke("UltimateTrades","openNetworkTrade",new Class[]{Player.class,Player.class},carrier,target);else Bukkit.dispatchCommand(carrier,"ultimateranks:invsee "+target.getName());}catch(Exception ex){tell(carrier,"Could not open the menu; no items were transferred.");}}},1,2);delayed.put(carrier.getUniqueId(),task);}
 }}catch(Exception ex){getLogger().warning("Rejected network bridge message ("+ex.getClass().getSimpleName()+")");}}
 private String dimension(World w){try{if((Boolean)network.getClass().getMethod("isAuxiliaryWorld",World.class).invoke(network,w))return "Auxiliary:"+((JavaPlugin)network).getConfig().getString("server-id")+":"+w.getName();}catch(ReflectiveOperationException ignored){}for(String dim:List.of("Overworld","Nether","End"))if(((JavaPlugin)network).getConfig().getString("worlds."+dim,dim.equals("Overworld")?"world":dim.equals("Nether")?"world_nether":"world_the_end").equals(w.getName()))return dim;throw new IllegalArgumentException("This world is not mapped by BlinkNetwork");}
 private World world(String dimension){if(!Set.of("Overworld","Nether","End").contains(dimension))throw new IllegalArgumentException();return Bukkit.getWorld(((JavaPlugin)network).getConfig().getString("worlds."+dimension,dimension.equals("Overworld")?"world":dimension.equals("Nether")?"world_nether":"world_the_end"));}
 private boolean safe(Location l){World w=l.getWorld();if(w==null||!w.getWorldBorder().isInside(l))return false;int y=l.getBlockY();if(y<=w.getMinHeight()||y+2>=w.getMaxHeight())return false;for(double dx:new double[]{-.31,.31})for(double dz:new double[]{-.31,.31}){int x=(int)Math.floor(l.getX()+dx),z=(int)Math.floor(l.getZ()+dz);if(!w.isChunkLoaded(x>>4,z>>4))return false;Material floor=w.getBlockAt(x,y-1,z).getType();if(!floor.isSolid()||Set.of(Material.MAGMA_BLOCK,Material.CACTUS,Material.CAMPFIRE,Material.SOUL_CAMPFIRE,Material.POWDER_SNOW).contains(floor))return false;for(int yy=y;yy<=Math.floor(l.getY()+1.8);yy++){var b=w.getBlockAt(x,yy,z);if(!b.isPassable()||b.isLiquid()||Set.of(Material.FIRE,Material.SOUL_FIRE,Material.SWEET_BERRY_BUSH,Material.WITHER_ROSE,Material.POINTED_DRIPSTONE).contains(b.getType()))return false;}}return true;}
 private void fail(Player p,Wire f,String why){send(p,new Wire(f.id(),"FAIL",p.getUniqueId(),List.of(why)));}
 private void locate(Player p,Wire f){if(!usable(p)||hidden(p)||!safe(p.getLocation())){fail(p,f,"Destination is unavailable or unsafe. Stand on solid, safe ground.");return;}Location l=p.getLocation();send(p,new Wire(f.id(),"LOCATION",p.getUniqueId(),List.of(dimension(l.getWorld()),""+l.getX(),""+l.getY(),""+l.getZ(),""+l.getYaw(),""+l.getPitch(),f.at(0),f.at(2))));}
 private void move(Player p,Wire f){if(!usable(p)||warming.containsKey(p.getUniqueId())){fail(p,f,"Teleport cancelled: player is busy, frozen or unavailable.");return;}try{String dim=f.at(0);double x=Double.parseDouble(f.at(1)),y=Double.parseDouble(f.at(2)),z=Double.parseDouble(f.at(3));float yaw=Float.parseFloat(f.at(4)),pitch=Float.parseFloat(f.at(5));int seconds=Integer.parseInt(f.at(6));if(!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||!Float.isFinite(yaw)||!Float.isFinite(pitch)||seconds<0||seconds>30)throw new IllegalArgumentException();World w=dim.startsWith("Auxiliary:")?p.getWorld():world(dim);if(w==null)throw new IllegalArgumentException();Location to=new Location(w,x,y,z,yaw,pitch);warming.put(p.getUniqueId(),new Warmup(f,p,p.getLocation().clone(),to,dim,System.currentTimeMillis()+seconds*1000L,UUID.fromString(f.at(8))));p.closeInventory();tell(p,seconds>0?"Teleporting in "+seconds+" seconds. Stay still and avoid damage. /tprCancel cancels.":"Preparing protected teleport…");}catch(Exception ex){fail(p,f,"Invalid or unavailable destination.");}}
 private void pulse(){for(Warmup w:new ArrayList<>(warming.values())){Player p=w.player;if(!usable(p)||!p.getWorld().equals(w.origin.getWorld())||p.getLocation().distanceSquared(w.origin)>.04){warming.remove(p.getUniqueId());fail(p,w.frame,"Teleport cancelled: player moved or is unavailable.");continue;}if(System.currentTimeMillis()<w.due)continue;warming.remove(p.getUniqueId());try{if(w.dimension.startsWith("Auxiliary:")){String[] descriptor=w.dimension.split(":",3);if(descriptor.length!=3)throw new IllegalArgumentException();
 @SuppressWarnings("unchecked") java.util.concurrent.CompletableFuture<Boolean> future=(java.util.concurrent.CompletableFuture<Boolean>)network.getClass().getMethod("networkWorldTeleport",Player.class,String.class,String.class,double.class,double.class,double.class,float.class,float.class).invoke(network,p,descriptor[1],descriptor[2],w.destination.getX(),w.destination.getY(),w.destination.getZ(),w.destination.getYaw(),w.destination.getPitch());
 future.whenComplete((ok,error)->Bukkit.getScheduler().runTask(this,()->{if(p.isOnline()){if(error==null&&Boolean.TRUE.equals(ok))send(p,new Wire(w.frame.id(),"MOVED",p.getUniqueId(),List.of()));else fail(p,w.frame,"Spawn world is unavailable; your inventory remains protected.");}}));continue;}
 boolean ok=(Boolean)home.invoke(network,p,w.dimension,w.destination.getX(),w.destination.getY(),w.destination.getZ(),w.destination.getYaw(),w.destination.getPitch());if(ok)send(p,new Wire(w.frame.id(),"MOVED",p.getUniqueId(),List.of()));else fail(p,w.frame,"This server is under maintenance or the route is unavailable. Try again later.");}catch(Exception ex){fail(p,w.frame,"Teleport could not start safely; your inventory is unchanged.");}}}
 private void staff(Player target,Wire f){try{if(!ready(target)){send(target,Wire.of("STAFF_REPLY",target.getUniqueId(),f.at(0),"Target data is loading or transferring; try again shortly."));return;}UUID actor=UUID.fromString(f.at(0));String name=f.at(1),role=f.at(2),command=f.at(3);String[] args=f.args().subList(4,f.args().size()).toArray(String[]::new);Consumer<String> reply=text->send(target,Wire.of("STAFF_REPLY",target.getUniqueId(),actor.toString(),text.length()>4000?text.substring(0,4000):text));if(command.equals("maxhomes"))invoke("UltimateHomes","applyNetworkHomeLimit",new Class[]{UUID.class,String.class,String[].class,Consumer.class},target.getUniqueId(),name,args,reply);
 else invoke("UltimateRanks","executeNetworkStaff",new Class[]{UUID.class,String.class,String.class,String.class,String[].class,Consumer.class},actor,name,role,command,args,reply);}catch(Exception ex){Throwable cause=ex instanceof InvocationTargetException invocation?invocation.getCause():ex;String message=cause instanceof IllegalArgumentException?cause.getMessage():"Remote staff action could not complete safely.";send(target,Wire.of("STAFF_REPLY",target.getUniqueId(),f.at(0),message));getLogger().warning("Remote staff command rejected ("+ex.getClass().getSimpleName()+")");}}
 private boolean connected(Player p){return System.currentTimeMillis()-proxySeen.getOrDefault(p.getUniqueId(),0L)<15000;}
 private boolean route(Player p,String line){String[] a=line.replaceFirst("^/","").trim().split("\\s+");if(a.length==0)return false;String c=Commands.canonical(a[0]);if(c.equals("staff")&&a.length>=2){a=Arrays.copyOfRange(a,1,a.length);c=Commands.canonical(a[0]);}
  if(!Commands.routed(c))return false;
  if(c.equals("rank")&&(a.length<3||!Set.of("add","remove","set","info").contains(a[1].toLowerCase(Locale.ROOT))))return false;
  if(Set.of("tp","bring").contains(c)&&a.length!=2)return false;
  if(Commands.STAFF.contains(c)&&a.length<2)return false;
  if(Commands.STAFF.contains(c)||c.equals("rank")||c.equals("maxhomes")){
   int index=c.equals("rank")?2:1;if(a.length<=index)return false;
   if(Bukkit.getPlayerExact(a[index])!=null||findNetworkPlayer(a[index])==null)return false;
  }
  if(c.equals("trade")&&(a.length<2||Set.of("help").contains(a[1].toLowerCase(Locale.ROOT))))return false;
  if(c.equals("trade")&&a[1].equalsIgnoreCase("cancel")){if(connected(p)){send(p,Wire.of("COMMAND",p.getUniqueId(),"trade","cancel"));}return false;}
  String permission=Commands.permission(c);if(permission!=null&&!p.hasPermission(permission)){tell(p,"You do not have permission.");return true;}
  if((c.equals("msg")||c.equals("reply"))&&(muted(p)||hidden(p))){tell(p,"Disable vanish and clear any mute before using private messages.");return true;}
  if(!connected(p)||!ready(p)){tell(p,"Network bridge is unavailable or player data is still loading.");return true;}
  if(line.length()>1500){tell(p,"Command is too long.");return true;}
  a[0]=c;publish(p,true);send(p,new Wire(UUID.randomUUID(),"COMMAND",p.getUniqueId(),List.of(a)));return true;
 }
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void command(PlayerCommandPreprocessEvent e){if(route(e.getPlayer(),e.getMessage()))e.setCancelled(true);}
 @Override public boolean onCommand(CommandSender s,Command command,String label,String[] args){if(!(s instanceof Player p)){s.sendMessage("UltimateNetwork 1.0.0. Use network player commands in-game.");return true;}if(command.getName().equals("ultimatenetwork")){tell(p,"Bridge "+(connected(p)?"online":"unavailable")+"; visible network players: "+rosters.getOrDefault(p.getUniqueId(),List.of()).size());return true;}return route(p,label+" "+String.join(" ",args));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void hurt(EntityDamageEvent e){if(e.getEntity() instanceof Player p){Warmup w=warming.remove(p.getUniqueId());if(w!=null)fail(p,w.frame,"Teleport cancelled: damage received.");}}
 private List<String> completions(Player p,String buffer){String[] a=buffer.split("\\s+",-1);if(a.length<2)return List.of();String c=Commands.canonical(a[0].replaceFirst("^/",""));if(!Commands.routed(c))return List.of();String permission=Commands.permission(c);if(permission!=null&&!tabPermissions.getOrDefault(p.getUniqueId(),Set.of()).contains(permission))return List.of();int at=c.equals("rank")?2:c.equals("trade")&&Set.of("accept","deny").contains(a[1])?2:1;if(a.length!=at+1)return List.of();String prefix=a[at].toLowerCase(Locale.ROOT);return rosters.getOrDefault(p.getUniqueId(),List.of()).stream().filter(r->!r.id.equals(p.getUniqueId())&&r.name.toLowerCase(Locale.ROOT).startsWith(prefix)).map(Remote::name).sorted().toList();}
 @EventHandler(priority=EventPriority.HIGHEST) public void tab(TabCompleteEvent e){if(e.getSender() instanceof Player p){List<String> list=completions(p,e.getBuffer());if(!list.isEmpty())e.setCompletions(list);}}
 @EventHandler(priority=EventPriority.HIGHEST) public void asyncTab(AsyncTabCompleteEvent e){if(e.getSender() instanceof Player p){List<String> list=completions(p,e.getBuffer());if(!list.isEmpty()){e.setCompletions(list);e.setHandled(true);}}}
 @Override public void onDisable(){Bukkit.getMessenger().unregisterIncomingPluginChannel(this);Bukkit.getMessenger().unregisterOutgoingPluginChannel(this);warming.clear();for(BukkitTask t:delayed.values())t.cancel();delayed.clear();}
}
